// ============================================================
// AJUSTE AQUI se mudar o template ou os nomes das colunas
// ============================================================
const TEMPLATE_NAME = 'advisor_inbound_form_1';
const TEMPLATE_LANG = 'pt_BR';

const row = $json;

const get = (...keys) => {
  for (const k of keys) {
    const v = row[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};

const nomeCompleto = get('Nome', 'nome', 'Cliente', 'clientes');
const primeiroNome = (nomeCompleto.split(/\s+/)[0] || '').trim();
const email = get('Email', 'email').toLowerCase();
const telefoneOriginal = get('Telefone', 'telefone', 'WhatsApp', 'whatsapp');

// mesma regra do Make: tira tudo que nao e digito e valida 10 a 13 digitos
let telefone = telefoneOriginal.replace(/\D/g, '').replace(/^0+/, '');
const telefoneOk = /^[0-9]{10,13}$/.test(telefone);
const nomeOk = nomeCompleto !== '';
const valido = telefoneOk && nomeOk;

let motivo = '';
if (!nomeOk) motivo = 'Nome vazio';
else if (!telefoneOk) motivo = 'Telefone invalido: ' + telefoneOriginal;

// campos de origem que o Make mandava para o CRM
const campanhas = get('Form', 'form', 'Campanha', 'campanhas') || 'Institucional';
const conjunto_anuncios = get('Conjunto', 'Conjunto de anuncios', 'Conjunto de anúncios', 'conjunto_anuncios', 'Adset');
const anuncios = get('Anuncio', 'Anúncio', 'anuncios', 'Ad', 'Criativo');

// texto do template advisor_inbound_form_1 (1 variavel = primeiro nome)
const mensagem = 'Oi ' + primeiroNome + ', tudo bem? Aqui e o Gabriel Monteferrario, da Finamob. '
  + 'Cuido do braco de advisor e vi seu cadastro no formulario do FinAdvisor. '
  + 'A gente prepara a incorporadora pra acessar capital, do numero a governanca. '
  + 'Te mostro em 30 min como funciona na pratica. Quais dias dessa semana ficam bons pra voce?';

return {
  json: {
    ...row,
    nome: nomeCompleto,
    primeiro_nome: primeiroNome,
    email,
    telefone,
    telefone_original: telefoneOriginal,
    valido,
    motivo,
    campanhas,
    conjunto_anuncios,
    anuncios,
    incorporadora: get('Incorporadora'),
    perfil: get('Incorporador'),
    template_name: TEMPLATE_NAME,
    template_lang: TEMPLATE_LANG,
    mensagem,
  },
};

